def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]

    markers = [(r, c, original[r][c])
               for r in range(h) for c in range(w)
               if original[r][c] not in (0, 1)]

    for r, c, color in markers:
        # The marker defines a 3x3 binary pattern; treat the marker itself
        # as foreground when forming the pattern.
        pattern = []
        for dr in (-1, 0, 1):
            row = []
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                row.append(1 if original[rr][cc] != 0 else 0)
            pattern.append(row)

        for r0 in range(h - 2):
            for c0 in range(w - 2):
                match = True
                for dr in range(3):
                    for dc in range(3):
                        value = 1 if original[r0 + dr][c0 + dc] != 0 else 0
                        if value != pattern[dr][dc]:
                            match = False
                            break
                    if not match:
                        break
                if match:
                    rr, cc = r0 + 1, c0 + 1
                    if original[rr][cc] != 0:
                        out[rr][cc] = color

    return out
