def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []

    # Foreground regions are connected through orthogonal neighbors.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] != 0 and not seen[yy][xx]):
                        seen[yy][xx] = True
                        stack.append((yy, xx))
            components.append(comp)

    for comp in components:
        colors = [grid[r][c] for r, c in comp if grid[r][c] not in (0, 1)]
        if not colors:
            continue
        color = colors[0]
        for r, c in comp:
            if 0 < r < h - 1 and 0 < c < w - 1:
                if all(grid[rr][cc] != 0
                       for rr in range(r - 1, r + 2)
                       for cc in range(c - 1, c + 2)):
                    out[r][c] = color

    return out
